// Bundles src/ into the 3 files you paste into Apps Script:
//   dist/Code.gs          — all server code
//   dist/Index.html       — the page (styles and script inlined)
//   dist/appsscript.json  — permissions and web app settings
// Run: npm run bundle
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const src = path.join(root, 'src');
const dist = path.join(root, 'dist');

function build() {
  const order = ['Config.gs', 'Plan.gs', 'FormDefs.gs', 'FormLogic.gs', 'Data.gs', 'People.gs', 'Requests.gs',
    'Design.gs', 'Calendar.gs', 'Notify.gs', 'Setup.gs', 'Import.gs', 'Code.gs'];
  const all = fs.readdirSync(src).filter(f => f.endsWith('.gs'));
  const missing = all.filter(f => !order.includes(f));
  if (missing.length) throw new Error('Add these files to the bundle order: ' + missing.join(', '));

  const header = '/**\n * Calvary Communications App — bundled from src/ by scripts/bundle.js.\n' +
    ' * Edit the files in src/ and run `npm run bundle`; do not edit this file directly.\n */\n';
  const code = header + order.map(f => '\n// ===== ' + f + ' =====\n\n' + fs.readFileSync(path.join(src, f), 'utf8').trim() + '\n').join('');

  let html = fs.readFileSync(path.join(src, 'Index.html'), 'utf8');
  html = html.replace(/<\?!= include\('(\w+)'\); \?>/g, (_, name) => fs.readFileSync(path.join(src, name + '.html'), 'utf8').trim());
  if (/include\(/.test(html)) throw new Error('Index.html still has an include() after bundling.');

  return {
    'Code.gs': code,
    'Index.html': html,
    'appsscript.json': fs.readFileSync(path.join(src, 'appsscript.json'), 'utf8')
  };
}

if (require.main === module) {
  fs.mkdirSync(dist, { recursive: true });
  const files = build();
  for (const [name, body] of Object.entries(files)) fs.writeFileSync(path.join(dist, name), body);
  console.log('Wrote', Object.keys(files).map(f => 'dist/' + f).join(', '));
}

module.exports = { build };
